//#region src/bundlers/webpack/shared/css-loader-runtime.ts
function isWebpackCssLoaderRuntimeSource(source) {
	if (source.trimStart().startsWith("// extracted by mini-css-extract-plugin")) return true;
	return source.includes("___CSS_LOADER_EXPORT___") && source.includes("___CSS_LOADER_API_IMPORT___") && (source.includes("module.exports = ___CSS_LOADER_EXPORT___") || source.includes("export default ___CSS_LOADER_EXPORT___"));
}
//#endregion
Object.defineProperty(exports, "isWebpackCssLoaderRuntimeSource", {
	enumerable: true,
	get: function() {
		return isWebpackCssLoaderRuntimeSource;
	}
});
